prog='''from collections import Counter

def _fix(g, noise):
    n = len(g)
    res = [row[:] for row in g]
    for i in range(n):
        for j in range(n):
            v = [g[i][j], g[i][n-1-j], g[n-1-i][j], g[n-1-i][n-1-j]]
            c = Counter(v)
            if len(c) > 1:
                c.pop(noise, None)
            res[i][j] = max(c, key=lambda x: (c[x], -x))
    return res

def _sym(g):
    n = len(g)
    return all(g[i][j] == g[i][n-1-j] == g[n-1-i][j] == g[n-1-i][n-1-j]
               for i in range(n) for j in range(n))

def transform(grid):
    candidates = [c for c in range(10)]
    # prefer colors that appear in symmetric-breaking configurations
    n = len(grid)
    bad = Counter()
    for i in range(n):
        for j in range(n):
            v = [grid[i][j], grid[i][n-1-j], grid[n-1-i][j], grid[n-1-i][n-1-j]]
            if len(set(v)) > 1:
                for x in set(v):
                    bad[x] += 1
    order = sorted(candidates, key=lambda c: -bad[c])
    for c in order:
        f = _fix(grid, c)
        if _sym(f):
            return f
    return _fix(grid, None)
